SELECT CASE WHEN d.budget >= 4116000 THEN 'high' WHEN d.budget >= 1998000 THEN 'mid' ELSE 'low' END AS budget_bucket, d.dept_name, SUM(CASE WHEN e.job_title = 'Analyst' THEN e.salary ELSE 0 END) AS analyst_salary FROM employees e INNER JOIN departments d ON e.dept_id = d.id GROUP BY CASE WHEN d.budget >= 4116000 THEN 'high' WHEN d.budget >= 1998000 THEN 'mid' ELSE 'low' END, d.dept_name;
